function formatDate(v){if(!v)return '—';const s=String(v);const d=new Date(s.length===7?s+'-01':s);return Number.isNaN(d.getTime())?s:d.toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'})}
