function normKey(k){return String(k??'').toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'')}
function flatten(obj,prefix='',out={}){
 if(obj===null||obj===undefined)return out;
 if(Array.isArray(obj)){if(obj.length<=8&&obj.every(x=>['string','number','boolean'].includes(typeof x)))out[prefix]=obj.join(', ');return out}
 if(typeof obj!=='object'){out[prefix]=obj;return out}
 Object.entries(obj).forEach(([k,v])=>{const p=prefix?prefix+'.'+k:k;if(v!==null&&typeof v==='object')flatten(v,p,out);else out[p]=v});return out
}
function pickDeep(obj,aliases){
 const flat=flatten(obj), wanted=aliases.map(normKey);
 for(const [path,val] of Object.entries(flat)){const last=normKey(path.split('.').pop());if(wanted.includes(last)&&val!==null&&val!=='')return val}
 for(const [path,val] of Object.entries(flat)){const nk=normKey(path);if(wanted.some(a=>nk.endsWith('_'+a)||nk===a)&&val!==null&&val!=='')return val}
 return null
}
function unwrap(x){return x&&typeof x==='object'&&'data'in x?x.data:x}
