const TRUSTED_CONNECT_ORIGINS=new Set(['https://mfdata.in','https://api.mfapi.in','https://portal.amfiindia.com','https://www.amfiindia.com']);
const TRUSTED_LINK_ORIGINS=new Set([...TRUSTED_CONNECT_ORIGINS,'https://www.amfiindia.com','https://www.njmutualfund.com','https://downloads.njmutualfund.com','https://www.alpha-grep.com','https://www.abakkusmf.com','https://www.sbimf.com','https://www.wealthcompanyamc.in','https://www.barodabnpparibasmf.in','https://www.miraeassetmf.co.in']);
function trustedNetworkUrl(input){
 const u=new URL(String(input));
 if(u.protocol!=='https:'||!TRUSTED_CONNECT_ORIGINS.has(u.origin))throw new Error('Blocked untrusted network destination');
 return u.href
}
function safeExternalUrl(input){
 try{const u=new URL(String(input));return u.protocol==='https:'&&TRUSTED_LINK_ORIGINS.has(u.origin)?u.href:'#'}catch{return '#'}
}
function assertResponseSize(r,maxBytes){const len=Number(r.headers.get('content-length')||0);if(len&&len>maxBytes)throw new Error('Response too large')}
async function fetchJson(url,retries=3){
 const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),30000);
 try{
  const safe=trustedNetworkUrl(url);const r=await fetch(safe,{headers:{Accept:'application/json'},signal:ctrl.signal,cache:'no-store',credentials:'omit',referrerPolicy:'no-referrer',redirect:'error',mode:'cors'});assertResponseSize(r,25*1024*1024);
  if((r.status===429||r.status>=500)&&retries){const retry=Number(r.headers.get('retry-after')||0);const wait=retry?retry*1000:Math.min(12000,750*Math.pow(2,3-retries)+Math.random()*500);await sleep(wait);return fetchJson(url,retries-1)}
  if(!r.ok)throw new Error('HTTP '+r.status);
  return await r.json();
 }finally{clearTimeout(timer)}
}
async function fetchText(url,retries=2){
 const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),30000);
 try{
  const safe=trustedNetworkUrl(url);const r=await fetch(safe,{headers:{Accept:'text/plain,*/*'},signal:ctrl.signal,cache:'no-store',credentials:'omit',referrerPolicy:'no-referrer',redirect:'error',mode:'cors'});assertResponseSize(r,25*1024*1024);
  if((r.status===429||r.status>=500)&&retries){await sleep(Math.min(10000,1000*Math.pow(2,2-retries)+Math.random()*500));return fetchText(url,retries-1)}
  if(!r.ok)throw new Error('HTTP '+r.status);return await r.text()
 }finally{clearTimeout(timer)}
}
