let dbPromise=null;
function openMasterDb(){
 if(dbPromise)return dbPromise;
 dbPromise=new Promise((resolve,reject)=>{
  if(!('indexedDB'in window)){resolve(null);return}
  const req=indexedDB.open(DB_NAME,MASTER_SCHEMA_VERSION);
  req.onupgradeneeded=()=>{const db=req.result;['dynamicFunds','schemeRegistry','syncRuns','fundStates','settings'].forEach(name=>{if(!db.objectStoreNames.contains(name))db.createObjectStore(name,{keyPath:name==='settings'?'key':name==='schemeRegistry'?'schemeCode':name==='syncRuns'?'id':'id'})})};
  req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)
 }).catch(()=>null);return dbPromise
}
async function dbAll(storeName){const db=await openMasterDb();if(!db)return[];return new Promise((resolve,reject)=>{const tx=db.transaction(storeName,'readonly'),req=tx.objectStore(storeName).getAll();req.onsuccess=()=>resolve(req.result||[]);req.onerror=()=>reject(req.error)}).catch(()=>[])}
async function dbPut(storeName,value){const db=await openMasterDb();if(!db)return false;return new Promise(resolve=>{const tx=db.transaction(storeName,'readwrite');tx.objectStore(storeName).put(value);tx.oncomplete=()=>resolve(true);tx.onerror=()=>resolve(false)})}
async function dbBulkPut(storeName,values){if(!values.length)return true;const db=await openMasterDb();if(!db)return false;return new Promise(resolve=>{const tx=db.transaction(storeName,'readwrite'),s=tx.objectStore(storeName);values.forEach(v=>s.put(v));tx.oncomplete=()=>resolve(true);tx.onerror=()=>resolve(false)})}
function fnvHash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return(h>>>0).toString(36).toUpperCase()}
function amcKey(v){return String(v||'Unknown AMC').toLowerCase().replace(/asset management( company)?/g,' ').replace(/mutual fund/g,' ').replace(/amc/g,' ').replace(/limited|ltd|private|pvt/g,' ').replace(/[^a-z0-9]+/g,' ').trim()}
function canonicalBaseName(v){return String(v||'').replace(/\([^)]*(direct|regular|idcw|dividend|growth)[^)]*\)/gi,' ').replace(/\b(direct|regular|institutional|retail)\b/gi,' ').replace(/\b(plan|option|growth|idcw|dividend|payout|pay\s*out|reinvestment|reinvest|bonus)\b/gi,' ').replace(/\b(daily|weekly|monthly|quarterly|half yearly|annual|fortnightly)\b/gi,' ').replace(/\b(formerly known as|formerly)\b.*$/gi,' ').replace(/[^a-zA-Z0-9&]+/g,' ').replace(/\s+/g,' ').trim()}
function baseKey(amc,name){return amcKey(amc)+'|'+canonicalBaseName(name).toLowerCase()}
function detectPlan(name,apiPlan=''){const s=(String(apiPlan)+' '+String(name)).toLowerCase();if(/\bdirect\b/.test(s))return'Direct';if(/\bregular\b/.test(s))return'Regular';return /\betf\b/.test(s)?'Direct':'Unknown'}
function detectOption(name){const s=String(name||'').toLowerCase();if(/\bgrowth\b/.test(s))return'Growth';if(/idcw|dividend/.test(s))return'IDCW';return'Unspecified'}
function classifyAsset(category,name=''){const s=(String(category)+' '+String(name)).toLowerCase();if(/debt scheme|liquid|overnight|gilt|duration|money market|corporate bond|credit risk/.test(s))return'Debt';if(/hybrid|balanced advantage|asset allocation|equity savings|arbitrage/.test(s))return'Hybrid';if(/solution oriented|retirement|children/.test(s))return'Solution Oriented';if(/gold|silver|commodity/.test(s))return'Commodity';if(/international|global|overseas|nasdaq|s&p 500|china|japan/.test(s))return'International';if(/index|etf|passive/.test(s))return'Passive';if(/equity scheme|large cap|mid cap|small cap|flexi cap|multi cap|elss|sectoral|thematic/.test(s))return'Equity';return'Other'}
function benchmarkGuess(category,name){const s=(String(category)+' '+String(name)).toLowerCase(),rules=[[/nifty\s*50/,'NIFTY 50 TRI','High'],[/nifty\s*next\s*50/,'NIFTY Next 50 TRI','High'],[/nifty\s*midcap\s*150/,'NIFTY Midcap 150 TRI','High'],[/nifty\s*smallcap\s*250/,'NIFTY Smallcap 250 TRI','High'],[/sensex/,'BSE SENSEX TRI','High'],[/large\s*&?\s*mid cap/,'NIFTY LargeMidcap 250 TRI','Medium'],[/large cap/,'NIFTY 100 TRI','Medium'],[/mid cap/,'NIFTY Midcap 150 TRI','Medium'],[/small cap/,'NIFTY Smallcap 250 TRI','Medium'],[/flexi cap|focused|elss/,'NIFTY 500 TRI','Medium'],[/liquid/,'NIFTY Liquid Index A-I','Medium'],[/overnight/,'NIFTY 1D Rate Index','Medium'],[/gilt/,'NIFTY All Duration G-Sec Index','Medium'],[/corporate bond/,'NIFTY Corporate Bond Index A-II','Medium'],[/banking.*psu/,'NIFTY Banking & PSU Debt Index A-II','Medium'],[/gold/,'Domestic Price of Gold','High'],[/silver/,'Domestic Price of Silver','High']];for(const[r,b,c]of rules)if(r.test(s))return[b,c];return['Benchmark not mapped','Low']}
function normalizeSchemeItem(item,source){
 const code=pickDeep(item,['scheme_code','schemeCode','amfi_code','code']);if(code===null)return null;
 const name=pickDeep(item,['scheme_name','schemeName','name'])||`Scheme ${code}`;
 const amc=pickDeep(item,['amc','fund_house','fundHouse','amc_name'])||'AMC not supplied';
 const category=pickDeep(item,['category','scheme_category','schemeCategory','sebi_category'])||'Category not supplied';
 const plan=detectPlan(name,pickDeep(item,['plan_type','plan']));
 return{rawItem:item,schemeCode:Number(code),name:String(name),baseName:canonicalBaseName(name)||String(name),amc:String(amc),category:String(category),asset:classifyAsset(category,name),plan,option:detectOption(name),familyId:pickDeep(item,['family_id','fund_family_id','scheme_family_id']),nav:n(pickDeep(item,['nav','latest_nav','latestNav'])),navDate:pickDeep(item,['nav_date','latest_nav_date','latestNavDate','date']),aum:n(pickDeep(item,['aum_cr','aum','fund_size_cr','fund_size','assets_under_management'])),aumDate:pickDeep(item,['aum_date','aum_as_of','as_of_date','data_date','portfolio_date']),ter:n(pickDeep(item,['expense_ratio','ter','total_expense_ratio'])),launch:pickDeep(item,['launch_date','inception_date','start_date']),active:pickDeep(item,['active','is_active','status']),source}
}
function parseAmfiNavAll(text){let amc='',category='';const out=[];for(const raw of String(text||'').split(/\r?\n/)){const line=raw.trim();if(!line||line.startsWith('Scheme Code;'))continue;const p=line.split(';');if(p.length>=6&&/^\d+$/.test(p[0].trim())){out.push(normalizeSchemeItem({scheme_code:p[0].trim(),scheme_name:p[3].trim(),nav:p[4].trim(),nav_date:p[5].trim(),amc,category},'AMFI NAVAll'))}else if(/^(Open Ended|Close Ended|Interval Fund)/i.test(line))category=line;else amc=line}return out.filter(Boolean)}
function rowFromNewFund(v,id){const row=Array(K.length).fill(null),[bench,conf]=benchmarkGuess(v.category,v.baseName);const put=(k,val)=>{if(ix[k]!==undefined)row[ix[k]]=val};put('id',id);put('amc',v.amc);put('name',v.baseName);put('category',v.category);put('asset',v.asset);put('variants',1);put('dCode',v.plan==='Direct'?v.schemeCode:null);put('rCode',v.plan==='Regular'?v.schemeCode:null);put('repCode',v.schemeCode);put('repPlan',v.plan);put('aum',v.aum);put('aumQuarter',v.aumDate||'Live sync');put('launch',v.launch);if(v.launch){const d=new Date(v.launch),age=(Date.now()-d.getTime())/31557600000;if(Number.isFinite(age)&&age>=0)put('age',Math.round(age*100)/100)}put('benchmark',bench);put('benchBasis','Automatic new-scheme category/name mapping');put('benchConfidence',conf);put('benchNote','Verify official benchmark in latest SID/factsheet');if(v.plan==='Direct')put('dter',v.ter);if(v.plan==='Regular')put('rter',v.ter);put('portfolioStatus','New scheme — live portfolio enrichment available on demand');put('apiUrl',null);put('reviewStatus','Newly discovered by master sync; verify latest SID/KIM/factsheet');return row}
function attachLiveVariant(f,v,now,changes){const m=metaFor(f),code=String(v.schemeCode);if(m.currentSchemeName&&m.currentSchemeName!==v.name){m.previousNames=[...(m.previousNames||[]),m.currentSchemeName].slice(-5);changes.renamed++}const known=[f.repCode,f.dCode,f.rCode].filter(Boolean).map(String).includes(code);if(v.option==='Growth'||v.option==='Unspecified'){if(v.plan==='Direct'&&!f.dCode){setRaw(f,'dCode',v.schemeCode);changes.newVariants++}if(v.plan==='Regular'&&!f.rCode){setRaw(f,'rCode',v.schemeCode);changes.newVariants++}if(!f.repCode){setRaw(f,'repCode',v.schemeCode);setRaw(f,'repPlan',v.plan)}if(!known)setRaw(f,'variants',(n(f.variants)||0)+1)}if((!f.amc||/not supplied|unknown/i.test(f.amc))&&v.amc)setRaw(f,'amc',v.amc);if((!f.category||/not supplied/i.test(f.category))&&v.category){setRaw(f,'category',v.category);setRaw(f,'asset',v.asset)}if(v.launch&&!f.launch)setRaw(f,'launch',v.launch);if(v.aum!==null)m.latestAum=Math.max(n(m.latestAum)||0,v.aum);m.aumDate=v.aumDate||m.aumDate;if(v.plan==='Direct'){if(v.nav!==null)m.directNav=v.nav;m.directNavDate=v.navDate||m.directNavDate;if(v.ter!==null)setRaw(f,'dter',v.ter)}if(v.plan==='Regular'){if(v.nav!==null)m.regularNav=v.nav;m.regularNavDate=v.navDate||m.regularNavDate;if(v.ter!==null)setRaw(f,'rter',v.ter)}const prefix=v.plan==='Regular'?'r':'d';[['1',['returns_1y','return_1y','one_year_return']],['3',['returns_3y','return_3y','three_year_return']],['5',['returns_5y','return_5y','five_year_return']],['10',['returns_10y','return_10y','ten_year_return']],['15',['returns_15y','return_15y','fifteen_year_return']]].forEach(([yr,aliases])=>{const rv=n(pickDeep(v.rawItem||v,aliases));if(rv!==null)setRaw(f,prefix+yr,rv)});m.familyId=v.familyId||m.familyId;m.lastSeen=now;m.status='Active';m.currentSchemeName=v.name;m.discoverySource=v.source;m.retrievedAt=now;if(!m.firstSeen)m.firstSeen=now}
function makeDynamicId(v){return'LIVE-'+fnvHash(baseKey(v.amc,v.baseName))}
async function loadDynamicFunds(){let records=await dbAll('dynamicFunds');if(!records.length){try{records=JSON.parse(store.get('mf-dynamic-funds-v6','[]'))}catch{records=[]}}const ids=new Set(funds.map(f=>f.id));for(const rec of records){if(!rec?.id||!Array.isArray(rec.row)||ids.has(rec.id))continue;const f=makeFund(rec.row);funds.push(f);ids.add(f.id);Object.assign(metaFor(f),rec.meta||{origin:'live',isNew:true})}const states=await dbAll('fundStates');const byId=new Map(funds.map(f=>[f.id,f]));states.forEach(s=>{const f=byId.get(s.id);if(f)Object.assign(metaFor(f),s.meta||{})});const settings=await dbAll('settings');const last=settings.find(x=>x.key==='lastSuccessfulSync')?.value;if(last){liveState.lastRun=last;liveState.lastSync=last.finishedAt||last.id||liveState.lastSync;liveState.sourceStatus=last.sources||[]}liveState.newFunds=funds.filter(f=>metaFor(f).origin==='live').length}
async function persistDynamicState(changedFunds,registry,run){const dyn=[...new Map(changedFunds.filter(f=>metaFor(f).origin==='live').map(f=>[f.id,{id:f.id,row:f.raw,meta:metaFor(f)}])).values()];if(dyn.length){const ok=await dbBulkPut('dynamicFunds',dyn);if(!ok){try{store.set('mf-dynamic-funds-v6',JSON.stringify(dyn))}catch{}}}await dbBulkPut('schemeRegistry',registry);const states=changedFunds.map(f=>({id:f.id,meta:{origin:metaFor(f).origin,isNew:metaFor(f).isNew,firstSeen:metaFor(f).firstSeen,lastSeen:metaFor(f).lastSeen,status:metaFor(f).status,currentSchemeName:metaFor(f).currentSchemeName,discoverySource:metaFor(f).discoverySource,missedSyncs:metaFor(f).missedSyncs||0,newVariant:metaFor(f).newVariant||false}}));await dbBulkPut('fundStates',states);await dbPut('syncRuns',run);await dbPut('settings',{key:'lastSuccessfulSync',value:run})}
function acquireSyncLock(){try{const key='mf-master-sync-lock-v6',old=JSON.parse(store.get(key,'{}')),now=Date.now();if(old.owner&&old.owner!==TAB_ID&&now-old.time<5*60*1000)return false;store.set(key,JSON.stringify({owner:TAB_ID,time:now}));return true}catch{return true}}
function releaseSyncLock(){try{const key='mf-master-sync-lock-v6',old=JSON.parse(store.get(key,'{}'));if(old.owner===TAB_ID)store.remove(key)}catch{}}
async function scanMfdata(){let offset=0,total=Infinity,pages=0,items=[];while(offset<total&&pages<40){const res=await fetchJson(`${API_BASE}/schemes?active_only=true&exclude_fmp=true&limit=1000&offset=${offset}&sort_by=name&order=asc`);const arr=listFromResponse(res);total=n(res.count)??n(res.total)??n(res?.data?.count)??(offset+arr.length);if(!arr.length)break;items.push(...arr.map(x=>normalizeSchemeItem(x,'mfdata.in')).filter(Boolean));offset+=arr.length;pages++;await sleep(120)}return{source:'mfdata.in',items,complete:offset>=total||items.length>=total,total,pages}}
async function scanAmfi(){const text=await fetchText(AMFI_NAV_ALL);const items=parseAmfiNavAll(text);return{source:'AMFI NAVAll',items,complete:items.length>1000,total:items.length,pages:1}}
async function scanMfapi(){let offset=0,items=[],pages=0;while(pages<40){const res=await fetchJson(`${MFAPI_BASE}/mf?limit=1000&offset=${offset}`);const arr=listFromResponse(res);if(!arr.length)break;items.push(...arr.map(x=>normalizeSchemeItem(x,'MFapi.in')).filter(Boolean));offset+=arr.length;pages++;if(arr.length<1000)break;await sleep(120)}return{source:'MFapi.in',items,complete:items.length>1000,total:items.length,pages}}
async function hydrateNewMfapi(items,knownCodes){const todo=items.filter(v=>!knownCodes.has(String(v.schemeCode))&&(/not supplied/i.test(v.amc)||/not supplied/i.test(v.category))).slice(0,80);let cursor=0;async function worker(){while(cursor<todo.length){const v=todo[cursor++];try{const res=await fetchJson(`${MFAPI_BASE}/mf/${v.schemeCode}/latest`,1),meta=res.meta||unwrap(res)?.meta||{};v.amc=meta.fund_house||v.amc;v.category=meta.scheme_category||v.category;v.asset=classifyAsset(v.category,v.name);const d=listFromResponse(res)[0]||res.data?.[0];if(d){v.nav=n(d.nav);v.navDate=d.date}}catch{}await sleep(120)}}await Promise.all(Array.from({length:4},worker));return items}
function refreshFilterOptions(){[['#amc','amc','All AMCs'],['#asset','asset','All asset classes'],['#category','category','All categories'],['#confidence','benchConfidence','All confidence levels']].forEach(([id,key,label])=>{const el=$(id);if(!el)return;const val=el.value;fillSelect(id,uniq(key),label);if([...el.options].some(o=>o.value===val))el.value=val})}
