  if(allVariants.length<1000){try{const scan=await scanMfapi();allVariants.push(...scan.items);fullComplete=fullComplete||scan.complete;sourceStatus.push({name:scan.source,status:'ok',items:scan.items.length,message:'Fallback scheme master and NAV history source'})}catch(e){sourceStatus.push({name:'MFapi.in',status:'error',items:0,message:e.message})}}
  if(!allVariants.length)throw new Error('All configured scheme-master sources were unavailable.');

  const existingRegistry=await dbAll('schemeRegistry'),regMap=new Map(existingRegistry.map(x=>[String(x.schemeCode),x]));const codeMap=new Map(),canonicalMap=new Map(),familyMap=new Map();
  funds.forEach(f=>{[f.repCode,f.dCode,f.rCode].filter(Boolean).forEach(c=>codeMap.set(String(c),f));canonicalMap.set(baseKey(f.amc,f.name),f);const fam=metaFor(f).familyId;if(fam)familyMap.set(String(fam),f)});
  await hydrateNewMfapi(allVariants,new Set(codeMap.keys()));
  const byCode=new Map();for(const v of allVariants){const old=byCode.get(String(v.schemeCode));if(!old||old.source!=='mfdata.in')byCode.set(String(v.schemeCode),v)}
  const seenCodes=new Set(),seenFunds=new Set(),changedFunds=new Set(),registryUpdates=[],newFundNames=[];let matched=0;
  for(const v of byCode.values()){
   const code=String(v.schemeCode);seenCodes.add(code);let f=codeMap.get(code)||(v.familyId&&familyMap.get(String(v.familyId)))||canonicalMap.get(baseKey(v.amc,v.baseName));
   if(!f&&(v.option==='Growth'||v.option==='Unspecified')){let id=makeDynamicId(v),suffix=2;while(funds.some(x=>x.id===id))id=makeDynamicId({...v,baseName:v.baseName+' '+suffix++});f=makeFund(rowFromNewFund(v,id));funds.push(f);const m=metaFor(f);Object.assign(m,{origin:'live',isNew:true,firstSeen:now,lastSeen:now,status:'Active',familyId:v.familyId,currentSchemeName:v.name,discoverySource:v.source});changes.newFunds++;newFundNames.push({name:f.name,amc:f.amc,category:f.category});canonicalMap.set(baseKey(f.amc,f.name),f);if(v.familyId)familyMap.set(String(v.familyId),f)}
   if(f){attachLiveVariant(f,v,now,changes);changedFunds.add(f);seenFunds.add(f.id);codeMap.set(code,f);matched++}
   const old=regMap.get(code);registryUpdates.push({schemeCode:v.schemeCode,name:v.name,amc:v.amc,category:v.category,plan:v.plan,option:v.option,familyId:v.familyId||null,fundId:f?.id||old?.fundId||null,source:v.source,firstSeen:old?.firstSeen||now,lastSeen:now,status:'Active',missedSyncs:0})
  }
