function applyFilters(){shown=60;const q=$('#search').value.trim().toLowerCase(),amc=$('#amc').value,asset=$('#asset').value,cat=$('#category').value,conf=$('#confidence').value,plan=$('#plan').value,portfolio=$('#portfolio').value;const aumMin=n($('#aumMin').value),terMax=n($('#terMax').value),c5=n($('#cagr5Min').value),c10=n($('#cagr10Min').value);const chips=new Set($$('.chip.active').map(x=>x.dataset.filter));
 filtered=funds.filter(f=>{if(q&&!`${f.name} ${f.amc} ${f.category} ${f.benchmark} ${f.repCode} ${metaFor(f).currentSchemeName||''} ${metaFor(f).discoverySource||''}`.toLowerCase().includes(q))return false;if(amc&&f.amc!==amc||asset&&f.asset!==asset||cat&&f.category!==cat||conf&&f.benchConfidence!==conf)return false;if(plan==='direct'&&!f.dCode||plan==='regular'&&!f.rCode||plan==='both'&&(!f.dCode||!f.rCode))return false;const aum=effectiveAum(f);if(aumMin!==null&&(aum===null||aum<aumMin))return false;if(terMax!==null&&(n(f.dter)===null||n(f.dter)>terMax))return false;if(c5!==null&&(n(f.d5)===null||n(f.d5)<c5))return false;if(c10!==null&&(n(f.d10)===null||n(f.d10)<c10))return false;const hp=hasLivePortfolio(f);if(portfolio==='yes'&&!hp||portfolio==='no'&&hp)return false;const fm=metaFor(f);if(chips.has('direct')&&!f.dCode||chips.has('regular')&&!f.rCode||chips.has('10y')&&n(f.d10)===null||chips.has('aum1000')&&(aum===null||aum<1000)||chips.has('benchmark')&&f.benchConfidence!=='High'||chips.has('new')&&!fm.isNew||chips.has('active')&&fm.status&&fm.status!=='Active')return false;return true});sortResults();saveFilters();render()
}
function sortResults(){const s=$('#sort').value,[key,dir]=s.split('-');const k={aum:'aum',d5:'d5',d10:'d10',sharpe:'dsharpe',ter:'dter',name:'name'}[key];filtered.sort((a,b)=>{let x=key==='aum'?effectiveAum(a):a[k],y=key==='aum'?effectiveAum(b):b[k];if(key==='name')return String(x||'').localeCompare(String(y||''))*(dir==='asc'?1:-1);x=n(x);y=n(y);if(x===null&&y===null)return 0;if(x===null)return 1;if(y===null)return-1;return(x-y)*(dir==='asc'?1:-1)})}
