async function openCompare(){const fs=selectedFunds();if(fs.length<2)return;$('#compareTitle').textContent=`Loading live data for ${fs.length} schemes…`;$('#compareTable').innerHTML='<tbody><tr><td style="padding:28px">Fetching latest available profiles and ratios. Embedded values remain as fallback.</td></tr></tbody>';$('#compareModal').classList.remove('hidden');await Promise.allSettled(fs.map(f=>enrichFund(f,false)));let html=`<thead><tr><th>Metric</th>${fs.map(f=>`<th>${esc(f.name)}<div class="compare-sub">${esc(f.amc)}</div></th>`).join('')}</tr></thead><tbody>`;html+=`<tr class="section-row"><td colspan="${fs.length+1}">Latest Fund Profile and Data Dates</td></tr>`;profileRows(fs).forEach(([l,get])=>{html+=`<tr><td>${esc(l)}</td>${fs.map(f=>`<td>${esc(get(f)??'—')}</td>`).join('')}</tr>`});const groups=[...new Set(M.map(m=>m.group))];groups.forEach(g=>{html+=`<tr class="section-row"><td colspan="${fs.length+1}">${esc(g)}</td></tr>`;M.filter(m=>m.group===g).forEach(metric=>{const vals=fs.map(f=>n(f[metric.key]));let best=null;if(metric.better&&vals.some(v=>v!==null)){const valid=vals.filter(v=>v!==null);best=metric.better==='high'?Math.max(...valid):Math.min(...valid)}html+=`<tr><td>${esc(metric.label)}</td>${fs.map((f,i)=>{const v=vals[i],cls=v===null?'missing':best!==null&&v===best?'best':'';return`<td class="${cls}">${value(f,metric.key,metric.unit)}</td>`}).join('')}</tr>`})});html+='</tbody>';$('#compareTable').innerHTML=html;$('#compareTitle').textContent=`Compare ${fs.length} schemes — live profile refresh attempted`}
