 const rows=nfoVisible();if($('#nfoCards'))$('#nfoCards').innerHTML=rows.length?rows.map(nfoCard).join(''):`<div class="nfo-empty">No ${nfoState.tab==='all'?'cached':nfoState.tab} NFOs match the current filters. Tap <b>Refresh NFOs</b> to check approved live sources.</div>`
