 const vals=rows.map(x=>[nfoStatusOf(x),x.name,x.amc,x.category,x.schemeType,x.openDate,x.closeDate,nfoDaysLabel(x),x.offerPrice,x.minimum,(x.reopenDate||x.reopenText),x.benchmark,x.objective,x.officialUrl,x.source,x.sourceDate,x.confidence]);const csv=[headers,...vals].map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\r\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`MoneyMantra9_NFOs_${new Date().toISOString().slice(0,10)}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)
